"use client";

import { useEffect, useId, useState, type CSSProperties } from "react";
import { scallopPath } from "@/app/_sections/testimonials/GoogleRatingBadge";

/**
 * Logo-Farben, wie das Logo auf der Website angezeigt wird (Header):
 * --green (GARAGE) und --orange (BEOGRAD) aus globals.css.
 * Als Hex-Werte, weil SVG-Verlaufsstopps keine CSS-Variablen auswerten.
 */
const SITE_GREEN = "#399d0e";
const SITE_ORANGE = "#f5a623";

/**
 * „Garage Beograd – 30 godina sa vama“ Jubiläums-Badge mit gewelltem Rand
 * wie das GoogleRatingBadge (gleiche Wellenform, gleiche relative Tiefe).
 *
 * Reines SVG, keine Abhängigkeiten außer React (18+).
 * Farbversionen in BADGE_THEMES, Auswahl per `variant`:
 *  - "logo" (Standard): Creme mit Grün und Orange aus dem Garage-Beograd-Logo,
 *    GARAGE grün und BEOGRAD orange wie im Logo
 *  - "classic": Creme, Dunkelgrün und Gold wie das GoogleRatingBadge
 *  - "gold": Gold auf Dunkelgrün
 * Bei Versionen mit `shine` (z. B. "gold") bekommen die Goldflächen einen subtilen, animierten Glanz:
 *  - ein diagonaler Lichtstreifen, der in Abständen über alle Goldelemente läuft
 *  - die Spiegelung im Außenring wandert langsam im Kreis
 * Bei „Bewegung reduzieren“ (prefers-reduced-motion) bleibt das Badge statisch.
 */
export interface AnniversaryBadgeProps {
  /** Breite/Höhe, z. B. 240 oder "100%". Standard: 300 */
  size?: number | string;
  /** Farbversion: "logo", "classic" oder "gold". Standard: "logo" */
  variant?: BadgeVariant;
  /** Anzahl der Wellen am Rand. Standard: 12 (wie das Google-Badge) */
  waves?: number;
  /** Hover: Badge vergrößert sich, der Wellenrand dreht sich langsam (Inhalt bleibt stehen). Standard: true */
  hoverEffect?: boolean;
  /** Vergrößerung beim Hover. Standard: 1.08 */
  hoverScale?: number;
  /** Dauer einer vollen Umdrehung des Rands beim Hover in Sekunden. Standard: 20 */
  hoverSpinDuration?: number;
  /** Glanz-Animation an/aus (nur bei Versionen mit Glanz, z. B. "gold"). Standard: true */
  animated?: boolean;
  /** Dauer eines Glanz-Durchlaufs inkl. Pause in Sekunden. Standard: 5 */
  shineDuration?: number;
  /** Dauer einer vollen Umdrehung der Ringspiegelung in Sekunden. Standard: 14 */
  ringDuration?: number;
  /**
   * Sprache des unteren Schriftzugs. Nur dieser Teil wechselt.
   * "sr-Latn" GODINA SA VAMA · "sr-Cyrl" ГОДИНА СА ВАМА · "en" YEARS WITH YOU · "de" JAHRE MIT IHNEN · "ru" ЛЕТ С ВАМИ
   * Standard: "sr-Latn"
   */
  language?: BadgeLanguage;
  className?: string;
  style?: CSSProperties;
  /** Barrierefreier Titel. Standard: "Garage Beograd – 30 " + Schriftzug der gewählten Sprache */
  title?: string;
}

