const stops = (list: Stop[]) =>
  list.map(([offset, color, opacity], index) => (
    <stop
      key={index}
      offset={offset}
      stopColor={color}
      stopOpacity={opacity}
    />
  ));

/* ---------- Komponente ---------- */

function usePrefersReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    if (typeof window === "undefined" || !window.matchMedia) return;
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    const update = () => setReduced(mq.matches);
    update();
    mq.addEventListener?.("change", update);
    return () => mq.removeEventListener?.("change", update);
  }, []);
  return reduced;
}

/* Rand-Geometrie wie beim GoogleRatingBadge (dort 182/166/160 bei viewBox 400),
   aber mit größerer Zeichenfläche (viewBox -25 -25 650 650): gleich dicker Rand wie dort (≈ 9 % bzw. 3 % des Radius) und Luft um den Schriftzug (bis r ≈ 245). */
const WAVE_DEPTH = 0.042;
const R_OUTER = 310;
const R_EDGE = 283;
const R_INNER = 273;
const wavy = (waves: number, radius: number) =>
  scallopPath(waves, radius, radius * WAVE_DEPTH, 300, 300);

export default function AnniversaryBadge({
  size = 300,
  variant = "logo",
  waves = 12,
  animated = true,
  shineDuration = 5,
  ringDuration = 14,
  className,
  style,
  language = "sr-Latn",
  title,
  hoverEffect = true,
  hoverScale = 1.08,
  hoverSpinDuration = 20,
}: AnniversaryBadgeProps) {
  const lang: BadgeLanguage =
    language in BOTTOM_TEXT_LABEL ? language : "sr-Latn";
  const bottomPath = TEXT_BOTTOM[lang];
  const label = title ?? `Garage Beograd – 30 ${BOTTOM_TEXT_LABEL[lang]}`;
  // useId liefert z. B. ":r0:" – Doppelpunkte entfernen, damit url(#…) überall sicher funktioniert
  const uid = useId().replace(/:/g, "");
  const id = (name: string) => `gb-${uid}-${name}`;
  const url = (name: string) => `url(#${id(name)})`;

  const reducedMotion = usePrefersReducedMotion();
  const animate = animated && !reducedMotion;
  const theme: BadgeTheme = BADGE_THEMES[variant] ?? BADGE_THEMES.logo;
  const shine = animate && theme.shine;

  // Drei Wellenlagen mit gleicher Phase: Außenrand, Linie, Innenfläche
  const outerShape = wavy(waves, R_OUTER);
  const edgeShape = wavy(waves, R_EDGE);
  const innerShape = wavy(waves, R_INNER);

  // Alle Goldflächen einmal als Liste – genutzt für die sichtbare Darstellung und für die Glanz-Maske
  const goldShapes = (
    fillFor: (kind: "text" | "textAccent" | "digit" | "leaf") => string,
  ) => (
    <>
      {/* Die ersten 6 Pfade sind GARAGE, danach BEOGRAD */}
      {LETTERS_TOP.map((d, i) => (
        <path
          key={`t${i}`}
          d={d}
          fill={fillFor(i < 6 ? "text" : "textAccent")}
        />
      ))}
      {/* key = Sprache → beim Wechsel wird der Pfad neu eingeblendet */}
      {bottomPath ? (
        <path
          key={`b-${lang}`}
          d={bottomPath}
          fill={fillFor("text")}
          className={animate ? id("fade") : undefined}
        />
      ) : (
        // Ohne fertigen Pfad: Schrift auf dem Bogen, auf volle Breite gestreckt
        <text
          key={`b-${lang}`}
          fill={fillFor("text")}
          fontFamily={ARC_FONT}
          fontWeight={700}
          fontSize={50}
          className={animate ? id("fade") : undefined}
        >
          <textPath
            href={`#${id("arc")}`}
            startOffset="50%"
            textAnchor="middle"
            textLength={ARC_TEXT_LENGTH}
            lengthAdjust="spacing"
          >
            {BOTTOM_TEXT_LABEL[lang].toUpperCase()}
          </textPath>
        </text>
      )}
      <path d={DIGIT_3} fill={fillFor("digit")} />
      <path d={DIGIT_0} fill={fillFor("digit")} fillRule="evenodd" />
      <path d={LEAF_RIGHT} fill={fillFor("leaf")} />
      <path
        d={LEAF_RIGHT}
        fill={fillFor("leaf")}
        transform="matrix(-1 0 0 1 600 0)"
      />
    </>
  );

  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="-25 -25 650 650"
      width={size}
      height={size}
      role="img"
      aria-label={label}
      className={[id("root"), className].filter(Boolean).join(" ")}
      style={style}
    >
      <title>{label}</title>
      {animate && (
        <style>{`@keyframes ${id("fadeIn")}{from{opacity:0}to{opacity:1}}.${id("fade")}{animation:${id("fadeIn")} .45s ease-out}`}</style>
      )}
      {hoverEffect && (
        // Hover: Badge wächst leicht (eigene CSS-Eigenschaft `scale`, verträgt sich mit
        // rotate/translate von außen), der Wellenrand dreht sich langsam. Beim Verlassen
        // bleibt der Rand stehen, wo er ist, statt zurückzuspringen.
        <style>{`@media (hover:hover) and (prefers-reduced-motion:no-preference){
.${id("root")}{transition:scale .45s cubic-bezier(.34,1.56,.64,1)}
.${id("root")}:hover{scale:${hoverScale}}
@keyframes ${id("spinKf")}{to{transform:rotate(360deg)}}
.${id("spin")}{transform-box:fill-box;transform-origin:center;animation:${id("spinKf")} ${hoverSpinDuration}s linear infinite;animation-play-state:paused}
.${id("root")}:hover .${id("spin")}{animation-play-state:running}
}`}</style>
      )}
      <defs>
        {/* Bogen für den unteren Schriftzug ohne fertigen Pfad */}
        <path id={id("arc")} d={ARC_PATH} fill="none" />

        {/* Hintergrund */}
        <radialGradient
          id={id("bg")}
          cx="300"
          cy="300"
          r="285"
          gradientUnits="userSpaceOnUse"
        >
          {stops(theme.background)}
        </radialGradient>

        {/* Außenring – Spiegelung dreht sich langsam */}
        <linearGradient
          id={id("ringOuter")}
          x1="26.5"
          y1="26.5"
          x2="573.5"
          y2="573.5"
          gradientUnits="userSpaceOnUse"
        >
          {stops(theme.ringOuter)}
          {shine && (
            <animateTransform
              attributeName="gradientTransform"
              type="rotate"
              from="0 300 300"
              to="360 300 300"
              dur={`${ringDuration}s`}
              repeatCount="indefinite"
            />
          )}
        </linearGradient>
        <linearGradient
          id={id("ringInner")}
          x1="566.659"
          y1="566.659"
          x2="33.341"
          y2="33.341"
          gradientUnits="userSpaceOnUse"
        >
          {stops(theme.ringInner)}
          {shine && (
            <animateTransform
              attributeName="gradientTransform"
              type="rotate"
              from="0 300 300"
              to="-360 300 300"
              dur={`${ringDuration * 1.4}s`}
              repeatCount="indefinite"
            />
          )}
        </linearGradient>
        <linearGradient
          id={id("ringGlow")}
          x1="26.1"
          y1="26.1"
          x2="573.9"
          y2="573.9"
          gradientUnits="userSpaceOnUse"
        >
          {stops(theme.ringGlow ?? [])}
          {shine && (
            <animateTransform
              attributeName="gradientTransform"
              type="rotate"
              from="0 300 300"
              to="360 300 300"
              dur={`${ringDuration}s`}
              repeatCount="indefinite"
            />
          )}
        </linearGradient>

        {/* Schrift: pro Buchstabe von oben nach unten */}
        <linearGradient id={id("text")} x1="0" y1="0" x2="0" y2="1">
          {stops(theme.text)}
        </linearGradient>
        <linearGradient id={id("textAccent")} x1="0" y1="0" x2="0" y2="1">
          {stops(theme.textAccent ?? theme.text)}
        </linearGradient>

        {/* 30: diagonal */}
        <linearGradient
          id={id("digit")}
          x1="0.19"
          y1="-0.045"
          x2="0.81"
          y2="1.045"
        >
          {stops(theme.digit)}
        </linearGradient>

        {/* Lorbeer */}
        <linearGradient
          id={id("leaf")}
          x1="-0.06"
          y1="0.007"
          x2="1.06"
          y2="0.99"
        >
          {stops(theme.leaf)}
        </linearGradient>

        {/* Glanzstreifen: weicher, diagonaler Lichtstreifen */}
        <linearGradient
          id={id("sheen")}
          x1="0"
          y1="0"
          x2="600"
          y2="600"
          gradientUnits="userSpaceOnUse"
        >
          <stop offset="0.38" stopColor="#ffffff" stopOpacity="0" />
          <stop offset="0.47" stopColor="#fffbe8" stopOpacity="0.35" />
          <stop offset="0.5" stopColor="#ffffff" stopOpacity="0.75" />
          <stop offset="0.53" stopColor="#fffbe8" stopOpacity="0.35" />
          <stop offset="0.62" stopColor="#ffffff" stopOpacity="0" />
          <animateTransform
            attributeName="gradientTransform"
            type="translate"
            values="-720 0; 720 0; 720 0"
            keyTimes="0; 0.5; 1"
            calcMode="spline"
            keySplines="0.4 0 0.6 1; 0 0 1 1"
            dur={`${shineDuration}s`}
            repeatCount="indefinite"
          />
        </linearGradient>

        {/* Maske = alle Goldflächen + Ring, damit der Glanz nur auf Gold liegt */}
        <mask
          id={id("goldMask")}
          maskUnits="userSpaceOnUse"
          x="-25"
          y="-25"
          width="650"
          height="650"
        >
          {/* Wellenrand = Außenform ohne Innenfläche, dreht sich mit */}
          <g className={id("spin")}>
            <path d={outerShape} fill="#fff" />
            <path d={innerShape} fill="#000" />
          </g>
          {goldShapes(() => "#fff")}
        </mask>
      </defs>

      {/* Grundaufbau: gewellter Außenrand, Linie, Innenfläche.
          Diese Gruppe dreht sich beim Hover, der Inhalt darüber bleibt stehen. */}
      <g className={id("spin")}>
        <path d={outerShape} fill={url("ringOuter")} />
        <path d={edgeShape} fill={url("ringInner")} />
        <path d={innerShape} fill={url("bg")} />

        {/* Feine Kanten am Rand */}
        {theme.ringGlow && (
          <path
            d={outerShape}
            fill="none"
            stroke={url("ringGlow")}
            strokeWidth="1.2"
          />
        )}
        {theme.ringEdges && (
          <>
            <path
              d={innerShape}
              fill="none"
              stroke={theme.ringEdges.inner}
              strokeWidth="1.2"
              opacity="0.55"
            />
            <path
              d={edgeShape}
              fill="none"
              stroke={theme.ringEdges.middle}
              strokeWidth="0.8"
              opacity="0.7"
            />
          </>
        )}
      </g>

      {goldShapes((kind) => url(kind))}

      {/* Animierter Glanz – nur auf den Goldflächen */}
      {shine && (
        <rect
          x="-25"
          y="-25"
          width="650"
          height="650"
          fill={url("sheen")}
          mask={url("goldMask")}
          style={{ mixBlendMode: "screen", pointerEvents: "none" }}
        />
      )}
    </svg>
  );
}
